# Brand main pages: /brands/<brand>/ for "<Brand> authorized dealer" searches. Each one introduces the brand and links
# down to its product pages (/brands/<brand>/heat-pumps/ etc.). Facts come from the product pages and data/pricing.py.
# Goodman's main page lives in brands-goodman.py.

def AUTH_WHY(b, reg):
    return {"type": "problems", "h2": f"Why buy {b} from an authorized dealer",
            "lead": f"Anyone can buy the box. What you get from an authorized {b} dealer is everything around it.",
            "items": [
             {"problem": "Your warranty, registered properly", "solution": f"{reg} We register it for you before we leave and send you the confirmation, so it is on file from day one."},
             {"problem": "Matched equipment, not mix and match", "solution": f"{b}'s rated efficiency and capacity apply to matched systems. We pair the outdoor unit, coil, furnace or air handler from {b}'s own matchups, so you get what the spec sheet promises."},
             {"problem": "Parts and support when you need them", "solution": f"As an authorized dealer we buy through {b}'s distribution in Ontario and have direct access to genuine parts and technical support, which shortens repairs."},
             {"problem": "Someone accountable after install day", "solution": f"We install, register, maintain and repair what we sell. If your {b} system ever needs service, you call the same company that put it in."}]}

def STEPS(b):
    return {"type": "steps", "h2": f"How buying {b} from us works",
            "items": [{"title": "Home visit", "text": "We measure your home, check ducts, venting and the electrical panel, and ask how you use it."},
                      {"title": "Model and written price", "text": f"We recommend the {b} model and size that fit, with model numbers and a guaranteed price."},
                      {"title": "Installation", "text": "Licensed technicians install it to the manufacturer's instructions and code, usually in one day."},
                      {"title": "Registration and handover", "text": f"We register your {b} warranty, file any rebate paperwork and show you how to use the system."}]}

def brand_page(k):
    B = k["brand"]
    return {
     "url": f"/brands/{k['slug']}/", "priority": "0.8",
     "title": k["title"], "description": k["description"],
     "eyebrow": f"Authorized {B} Dealer", "h1": f"Authorized {B} Dealer in Ontario", "tagline": k["tagline"],
     "intro": k["intro"], "hero_points": k["points"],
     "hero_center": True,
     "service": {"name": f"{B} Installation, Repair and Maintenance", "type": f"Authorized {B} dealer"},
     "blocks": [
      {"type": "cards", "h2": f"{B} equipment we install", "lead": k["lines_lead"], "items": k["lines"], "fill_h": f"Not sure which {B} system fits your home?", "fill_text": f"Tell us how you heat and cool today, and we'll recommend the right {B} model with a guaranteed written price."},
      {"type": "table", "h2": f"The {B} lineup at a glance", "headers": ["Model", "Type", "Key specs"], "rows": k["models"], "note": k["models_note"]},
      AUTH_WHY(B, k["warranty"]),
      STEPS(B),
      {"type": "split", "h2": k["service_h2"], "image": k["service_alt"], "image_src": k["service_img"], "image_fit": "cover", "image_credit": "EHI install", "html": k["service_html"]},
      {"type": "money"}, {"type": "why"}, {"type": "areas"}],
     "faqs": k["faqs"],
     "related": [i["link"] for i in k["lines"]] + ["/brands/"],
    }

